type SmsTarget={id:string;name:string;phone:string;group:string;studentId?:string};
const smsPhone=(value:unknown)=>normalize(String(value||'')).replace(/\D/g,'');
export function buildSmsTargets(d:School,l:Life,yearId:string):SmsTarget[]{
 const active=new Set(d.enrollments.filter(e=>e.yearId===yearId&&e.status==='active').map(e=>e.studentId));
 const rows:SmsTarget[]=[];
 for(const s of d.students){const phone=smsPhone(s.phone);if(active.has(s.id)&&/^09\d{9}$/.test(phone))rows.push({id:'student:'+s.id,name:s.name,phone,group:'student',studentId:s.id})}
 for(const t of d.teachers){const phone=smsPhone(t.phone);if(/^09\d{9}$/.test(phone))rows.push({id:'teacher:'+t.id,name:t.name,phone,group:'teacher'})}
 for(const [id,c] of Object.entries(l.contacts)){const phone=smsPhone(c.phone);if(c.consent&&/^09\d{9}$/.test(phone))rows.push({id:'contact:'+id,name:c.name,phone,group:c.group,studentId:c.studentId})}
 return rows;
}
